import { test, expect } from '@playwright/test';

test.describe('Checkout Flow', () => {
  test('completes purchase successfully', async ({ page }) => {
    // 1. Navigate to product page and add item to cart
    await page.goto('/products/sample-item');
    await page.getByRole('button', { name: 'Add to Cart' }).click();

    // 2. Proceed to checkout
    await page.getByRole('link', { name: 'Cart' }).click();
    await page.getByRole('button', { name: 'Proceed to Checkout' }).click();

    // 3. Fill shipping information
    await page.getByLabel('Full Name').fill('Jane Doe');
    await page.getByLabel('Address').fill('123 Main St');
    await page.getByLabel('City').fill('Anytown');
    await page.getByLabel('ZIP Code').fill('12345');

    // 4. Submit checkout
    await page.getByRole('button', { name: 'Place Order' }).click();

    // 5. Verify confirmation screen
    await expect(page.getByRole('heading', { name: 'Thank you for your order!' })).toBeVisible();
    await expect(page.locator('.order-confirmation-id')).not.toBeEmpty();
  });
});

