import express from 'express';
import rateLimit from 'express-rate-limit';

const app = express();

// Define rate limiter middleware
const apiLimiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute window
  max: 100, // Limit each client IP to 100 requests per windowMs
  standardHeaders: true, // Return standard rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers in favor of standard RFC headers
  statusCode: 429,
  message: {
    error: 'Too Many Requests',
    message: 'You have exceeded the rate limit. Please try again later.'
  },
  keyGenerator: (req) => {
    // Rate limit by authenticated user ID if available, falling back to IP
    return req.user ? req.user.id : req.ip;
  }
});

// Apply rate limiting middleware globally or to specific API routes
app.use('/api/', apiLimiter);

app.get('/api/resource', (req, res) => {
  res.json({ message: 'Request successful' });
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

// 1. Control Flow Narrowing (If Check / Early Return)
function printLength(text: string): void {
  console.log(text.length);
}

function handleInput(input?: string): void {
  if (input !== undefined) {
    // TypeScript narrows 'input' from 'string | undefined' to 'string'
    printLength(input);
  }
}

// 2. Default Parameter Value
function greet(name: string = "Guest"): void {
  console.log(`Hello, ${name.toUpperCase()}`);
}

let username: string | undefined = undefined;
greet(username); // Works: defaults to "Guest"

