execute(knownCommand!);

import { describe, it, expect } from 'vitest';
import { formatDate } from './dateUtils';

describe('formatDate', () => {
  it('should correctly format single-digit months and days with leading zeros', () => {
    // Arrange
    const inputDate = new Date('2026-03-05T00:00:00Z');
    const expectedOutput = '2026-03-05';

    // Act
    const result = formatDate(inputDate);

    // Assert
    expect(result).toBe(expectedOutput);
  });

  it('should handle leap year dates without shifting days', () => {
    // Arrange
    const leapYearDate = new Date('2024-02-29T12:00:00Z');
    const expectedOutput = '2024-02-29';

    // Act
    const result = formatDate(leapYearDate);

    // Assert
    expect(result).toBe(expectedOutput);
  });
});

export default {
  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
    const url = new URL(request.url);

    if (url.pathname === "/api/hello") {
      return new Response(JSON.stringify({ message: "Hello from the edge!" }), {
        headers: { "Content-Type": "application/json" },
      });
    }

    return new Response("Not Found", { status: 404 });
  },
};

